import csv
import io
import re
from typing import Any, Dict, List


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","
    quotechar = '"'

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar=quotechar,
        doublequote=True,
        strict=False,
    )

    records: List[List[str]] = []
    try:
        for record in reader:
            if record:
                records.append(list(record))
    except csv.Error:
        pass

    if records and records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    def is_blank(record: List[str]) -> bool:
        return not record or all(value.strip() == "" for value in record)

    def normalize(record: List[str]) -> List[str]:
        values = list(record)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [
                delimiter.join(values[expected_width - 1:])
            ]
        return values

    def header_score(record: List[str]) -> float:
        if is_blank(record):
            return -1000.0

        values = [value.strip() for value in record]
        nonempty = [value for value in values if value]
        if not nonempty:
            return -1000.0

        score = float(len(nonempty) * 3)
        if len(record) == expected_width:
            score += 12.0
        elif len(record) >= expected_width - 1:
            score += 5.0

        average_length = sum(len(value) for value in nonempty) / len(nonempty)
        score -= min(average_length, 200.0) * 0.08

        labelish = 0
        for value in nonempty:
            if (
                re.search(r"[A-Za-z]", value)
                and len(value) <= 40
                and not re.match(r"^\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}$", value)
                and not re.match(r"^\d+(?:\.\d+)?$", value)
            ):
                labelish += 1
        score += labelish * 1.5

        first = values[0] if values else ""
        if re.match(r"^\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}$", first):
            score -= 12.0
        elif re.match(r"^\d+(?:\.\d+)?$", first):
            score -= 6.0

        return score

    nonblank_indices = [
        index for index, record in enumerate(records) if not is_blank(record)
    ]

    if not nonblank_indices:
        return {
            "columns": [""] * expected_width,
            "rows": [],
        }

    search_indices = nonblank_indices[:40]
    header_index = max(search_indices, key=lambda index: header_score(records[index]))
    header = normalize(records[header_index])

    data_rows: List[List[str]] = []
    for record in records[header_index + 1:]:
        if not is_blank(record):
            data_rows.append(normalize(record))

    return {
        "columns": header,
        "rows": data_rows,
    }
